/* 执行规约动作 */
static void yy_reduce(int rule_num, int* top, YYSTYPE* stack, int* state_stack) {
  int symbols_to_pop = yyr2[rule_num];
  printf("  规约详情: 规则%d, 当前栈顶=%d, 弹出%d个符号\n", rule_num, *top, symbols_to_pop);
  YYSTYPE yyval;

  /* 计算栈中元素的位置, $1 是栈中第一个要规约的元素 */
  /* 对应关系: $1 = yyvsp[1], $2 = yyvsp[2], 以此类推 */
  YYSTYPE yyvsp[YYMAXDEPTH + 1]; // 临时数组，下标从1开始
  for (int i = 1; i <= symbols_to_pop; i++) {
    yyvsp[i] = stack[*top - symbols_to_pop + i];
  }

  /* 默认动作: 将$1的值赋给$$ */
  if (symbols_to_pop > 0) {
    yyval = yyvsp[1]; // $$ = $1
  }

  /* 根据规则执行语义动作 */
  printf("  执行语义动作: 规则%d\n", rule_num);
  switch(rule_num) {
    case 0: /* S' -> program  */
      break;
    case 1: /* program -> main_function  */
      {
        
        yyval.node = create_node(AST_PROGRAM, NULL);
        add_child(yyval.node, yyvsp[1].node);
        ast_root = yyval.node;
    
        printf("    完成语义动作: %s\n", "program");
      }
      break;
    case 2: /* main_function -> type_specifier MAIN '(' ')' compound_statement  */
      {
        
        yyval.node = create_node(AST_MAIN_FUNC, "main");
        add_child(yyval.node, yyvsp[1].node);
        add_child(yyval.node, yyvsp[5].node);
    
        printf("    完成语义动作: %s\n", "main_function");
      }
      break;
    case 3: /* type_specifier -> INT  */
      {
        
        yyval.node = create_node(AST_TYPE_SPEC, "int");
    
        printf("    完成语义动作: %s\n", "type_specifier");
      }
      break;
    case 4: /* type_specifier -> CHAR  */
      {
        
        yyval.node = create_node(AST_TYPE_SPEC, "char");
    
        printf("    完成语义动作: %s\n", "type_specifier");
      }
      break;
    case 5: /* type_specifier -> VOID  */
      {
        
        yyval.node = create_node(AST_TYPE_SPEC, "void");
    
        printf("    完成语义动作: %s\n", "type_specifier");
      }
      break;
    case 6: /* compound_statement -> LBRACE opt_declaration_list opt_statement_list RBRACE  */
      {
        
        yyval.node = create_node(AST_COMPOUND_STMT, NULL);
        if (yyvsp[2].node) add_child(yyval.node, yyvsp[2].node);
        if (yyvsp[3].node) add_child(yyval.node, yyvsp[3].node);
    
        printf("    完成语义动作: %s\n", "compound_statement");
      }
      break;
    case 7: /* opt_declaration_list -> declaration_list  */
      {
        
        yyval.node = yyvsp[1].node;
    
        printf("    完成语义动作: %s\n", "opt_declaration_list");
      }
      break;
    case 8: /* opt_declaration_list -> ε */
      {
        
        yyval.node = NULL;
    
        printf("    完成语义动作: %s\n", "opt_declaration_list");
      }
      break;
    case 9: /* opt_statement_list -> statement_list  */
      {
        
        yyval.node = yyvsp[1].node;
    
        printf("    完成语义动作: %s\n", "opt_statement_list");
      }
      break;
    case 10: /* opt_statement_list -> ε */
      {
        
        yyval.node = NULL;
    
        printf("    完成语义动作: %s\n", "opt_statement_list");
      }
      break;
    case 11: /* declaration_list -> declaration  */
      {
        
        yyval.node = create_node(AST_DECL_LIST, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "declaration_list");
      }
      break;
    case 12: /* declaration_list -> declaration_list declaration  */
      {
        
        yyval.node = yyvsp[1].node;
        add_child(yyval.node, yyvsp[2].node);
    
        printf("    完成语义动作: %s\n", "declaration_list");
      }
      break;
    case 13: /* declaration -> type_specifier init_declarator_list SEMICOLON  */
      {
        
        yyval.node = create_node(AST_DECL, NULL);
        add_child(yyval.node, yyvsp[1].node);
        add_child(yyval.node, yyvsp[2].node);
    
        printf("    完成语义动作: %s\n", "declaration");
      }
      break;
    case 14: /* init_declarator_list -> init_declarator  */
      {
        
        yyval.node = create_node(AST_INIT_LIST, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "init_declarator_list");
      }
      break;
    case 15: /* init_declarator_list -> init_declarator_list ',' init_declarator  */
      {
        
        yyval.node = yyvsp[1].node;
        add_child(yyval.node, yyvsp[3].node);
    
        printf("    完成语义动作: %s\n", "init_declarator_list");
      }
      break;
    case 16: /* init_declarator -> IDENTIFIER  */
      {
        
        yyval.node = create_node(AST_INIT, NULL);
        add_child(yyval.node, create_node(AST_ID, yyvsp[1].sval));
    
        printf("    完成语义动作: %s\n", "init_declarator");
      }
      break;
    case 17: /* init_declarator -> IDENTIFIER '=' initializer  */
      {
        
        yyval.node = create_node(AST_INIT, NULL);
        add_child(yyval.node, create_node(AST_ID, yyvsp[1].sval));
        add_child(yyval.node, yyvsp[3].node);
    
        printf("    完成语义动作: %s\n", "init_declarator");
      }
      break;
    case 18: /* initializer -> expression  */
      {
        
        yyval.node = yyvsp[1].node;
    
        printf("    完成语义动作: %s\n", "initializer");
      }
      break;
    case 19: /* statement_list -> statement  */
      {
        
        yyval.node = create_node(AST_STMT_LIST, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "statement_list");
      }
      break;
    case 20: /* statement_list -> statement_list statement  */
      {
        
        yyval.node = yyvsp[1].node;
        add_child(yyval.node, yyvsp[2].node);
    
        printf("    完成语义动作: %s\n", "statement_list");
      }
      break;
    case 21: /* statement -> expression_statement  */
      {
        
        yyval.node = create_node(AST_STMT, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "statement");
      }
      break;
    case 22: /* statement -> compound_statement  */
      {
        
        yyval.node = create_node(AST_STMT, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "statement");
      }
      break;
    case 23: /* statement -> printf_statement  */
      {
        
        yyval.node = create_node(AST_STMT, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "statement");
      }
      break;
    case 24: /* statement -> return_statement  */
      {
        
        yyval.node = create_node(AST_STMT, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "statement");
      }
      break;
    case 25: /* expression_statement -> expression SEMICOLON  */
      {
        
        yyval.node = create_node(AST_EXPR_STMT, NULL);
        add_child(yyval.node, yyvsp[1].node);
    
        printf("    完成语义动作: %s\n", "expression_statement");
      }
      break;
    case 26: /* expression_statement -> SEMICOLON  */
      {
        
        yyval.node = create_node(AST_EXPR_STMT, NULL);
    
        printf("    完成语义动作: %s\n", "expression_statement");
      }
      break;
    case 27: /* printf_statement -> PRINTF '(' STRING_LITERAL ',' expression ')' SEMICOLON  */
      {
        
        yyval.node = create_node(AST_PRINTF_STMT, NULL);
        add_child(yyval.node, create_node(AST_STRING_LITERAL, yyvsp[3].sval));
        add_child(yyval.node, yyvsp[5].node);
    
        printf("    完成语义动作: %s\n", "printf_statement");
      }
      break;
    case 28: /* printf_statement -> PRINTF '(' STRING_LITERAL ')' SEMICOLON  */
      {
        
        yyval.node = create_node(AST_PRINTF_STMT, NULL);
        add_child(yyval.node, create_node(AST_STRING_LITERAL, yyvsp[3].sval));
    
        printf("    完成语义动作: %s\n", "printf_statement");
      }
      break;
    case 29: /* return_statement -> RETURN expression SEMICOLON  */
      {
        
        yyval.node = create_node(AST_RETURN_STMT, NULL);
        add_child(yyval.node, yyvsp[2].node);
    
        printf("    完成语义动作: %s\n", "return_statement");
      }
      break;
    case 30: /* return_statement -> RETURN SEMICOLON  */
      {
        
        yyval.node = create_node(AST_RETURN_STMT, NULL);
    
        printf("    完成语义动作: %s\n", "return_statement");
      }
      break;
    case 31: /* expression -> IDENTIFIER  */
      {
        
        yyval.node = create_node(AST_EXPR, NULL);
        add_child(yyval.node, create_node(AST_ID, yyvsp[1].sval));
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 32: /* expression -> INTEGER_LITERAL  */
      {
        
        char buffer[32];
        sprintf(buffer, "%d", yyvsp[1].ival);
        yyval.node = create_node(AST_EXPR, NULL);
        add_child(yyval.node, create_node(AST_INT_LITERAL, buffer));
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 33: /* expression -> expression '+' expression  */
      {
        
        yyval.node = create_node(AST_EXPR, NULL);
        ASTNode* binary = create_node(AST_BINARY_EXPR, "+");
        add_child(binary, yyvsp[1].node);
        add_child(binary, yyvsp[3].node);
        add_child(yyval.node, binary);
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 34: /* expression -> expression '-' expression  */
      {
        
        yyval.node = create_node(AST_EXPR, NULL);
        ASTNode* binary = create_node(AST_BINARY_EXPR, "-");
        add_child(binary, yyvsp[1].node);
        add_child(binary, yyvsp[3].node);
        add_child(yyval.node, binary);
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 35: /* expression -> expression '*' expression  */
      {
        
        yyval.node = create_node(AST_EXPR, NULL);
        ASTNode* binary = create_node(AST_BINARY_EXPR, "*");
        add_child(binary, yyvsp[1].node);
        add_child(binary, yyvsp[3].node);
        add_child(yyval.node, binary);
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 36: /* expression -> expression '/' expression  */
      {
        
        yyval.node = create_node(AST_EXPR, NULL);
        ASTNode* binary = create_node(AST_BINARY_EXPR, "/");
        add_child(binary, yyvsp[1].node);
        add_child(binary, yyvsp[3].node);
        add_child(yyval.node, binary);
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 37: /* expression -> IDENTIFIER '=' expression  */
      {
        
        yyval.node = create_node(AST_EXPR, NULL);
        ASTNode* assign = create_node(AST_ASSIGN_EXPR, "=");
        add_child(assign, create_node(AST_ID, yyvsp[1].sval));
        add_child(assign, yyvsp[3].node);
        add_child(yyval.node, assign);
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
    case 38: /* expression -> '(' expression ')'  */
      {
        
        yyval.node = yyvsp[2].node;
    
        printf("    完成语义动作: %s\n", "expression");
      }
      break;
  }

  /* 保存归约结果，主函数负责调整栈 */
  stack[*top - symbols_to_pop + 1] = yyval;
}

/* 语法分析主函数 */
int yyparse(void) {
  int state = 0;
  int top = 0;
  int token;
  int action;
  YYSTYPE stack[YYMAXDEPTH];
  int state_stack[YYMAXDEPTH];

  printf("====== 开始语法分析 ======\n");
  state_stack[0] = 0;
  token = yylex();
  printf("获取首个token: %d\n", token);

  while (1) {
    printf("当前状态: %d, token: %d\n", state, token);
    action = yytable[state * YYNTOKENS + token];

    printf("查找动作: yytable[%d * %d + %d] = %d\n", state, YYNTOKENS, token, action);

    if (action == -32767) { /* 错误 */
      yyerror("语法错误");
      return 1;
    }

    if (action > 0) { /* 移入 */
      printf("执行移入操作: 状态%d -> 状态%d\n", state, action);
      stack[++top] = yylval;
      state_stack[top] = action;
      state = action;
      token = yylex();
      printf("获取下一个token: %d\n", token);
    } else if (action < 0) { /* 规约 */
      int rule = -action - 1;
      printf("执行规约操作: 使用规则%d\n", rule);
      yy_reduce(rule, &top, stack, state_stack);
      printf("规约后的栈顶位置: %d\n", top);
      /* 弹出状态栈中的规约符号对应的状态 */
      int symbols_to_pop = yyr2[rule];
      top -= symbols_to_pop;
      printf("规约后的状态栈顶: %d, 当前状态: %d\n", top, state_stack[top]);
      /* 通过GOTO表确定新状态 */
      int nonterminal = yyr1[rule] - YYNTOKENS;
      int goto_index = state_stack[top] * YYNNTS + nonterminal;
      printf("GOTO表查询: 状态%d + 非终结符%d, 索引=%d\n", state_stack[top], nonterminal, goto_index);
      if (goto_index < 0 || goto_index >= 1751) {
        printf("错误: GOTO表索引越界! goto_index=%d\n", goto_index);
        yyerror("GOTO表索引错误");
        return 3;
      }
      int next_state = yygoto[goto_index];
      printf("GOTO表结果: [%d][%d] = %d\n", state_stack[top], nonterminal, next_state);
      if (next_state == -1) {
        printf("错误: GOTO表中没有对应项! 状态%d, 非终结符%d\n", state_stack[top], nonterminal);
        yyerror("GOTO表错误");
        return 2;
      }
      /* 将新状态压入栈 */
      state_stack[++top] = next_state;
      state = next_state;
      printf("规约后的新状态: %d\n", state);
    } else { /* 接受 */
      printf("接受输入, 分析成功完成!\n");
      return 0;
    }
    printf("--------------------\n");
  }
  printf("====== 语法分析结束 ======\n");
}

/* 用户代码 */

extern int yylex();
extern int line_number;
extern char* yytext;

void yyerror(const char *s)
{
    fflush(stdout);
    fprintf(stderr, "错误 (行 %d): %s\n", line_number, s);
}

int main() {
    yyparse();
    
    if (ast_root) {
        printf("\n=== 生成抽象语法树 ===\n");
        print_ast_dot(ast_root);
        printf("\nTotal nodes: %d\n", node_count);
        free_ast(ast_root);
    }
    
    return 0;
}

